// === Tab: mySketch.js ===
/*
It is a 2D shader made for the weekly Creative Coding Challenge
(https://openprocessing.org/curation/78544) on the theme "Beautiful Burnout".

On this subject, I was reminded of the unceasing radiance of a
high-achiever, which shines with such vigour, colour and versatility,
until suddenly the colours fade noticeably and the vigour wanes.

Interaction:
- Space Bar: Pause/Play
- Mouse Wheel: Forward / Backward in time

*/

const scale = Math.max(1, devicePixelRatio)
let theShader, wheelDelta = 0, wheelOffset = 0, pause = false, paused = 0, time = 0

function preload(){
	theShader = loadShader('https://openprocessing.org/sketch/2965966/files/vert.glsl', 'frag.glsl')
}

function setup() {
	pixelDensity(scale)
	createCanvas(windowWidth, windowHeight, WEBGL)
}

function windowResized() {
	pixelDensity(scale)
	resizeCanvas(windowWidth, windowHeight)
}

function mouseWheel(e) {
	if (wheelDelta * e.deltaY < 0) {
		wheelDelta = e.deltaY
	} else {
		wheelDelta = lerp(wheelDelta, e.deltaY, .05)
	}
	wheelOffset += wheelDelta
}

function keyPressed(e) {
	if (e.key === " ") {
		if (!pause) {
			pause = true
		} else {
			pause = false
			paused = millis() - time
		}
	}
}

function draw() {
  shader(theShader)
  if (!pause) time = millis() - paused
  theShader.setUniform("resolution", [width * scale, height * scale])
  theShader.setUniform("wheel", [wheelDelta, wheelOffset])
  theShader.setUniform("time", time / 1000.0)
  rect(0, 0, width, height)
}

// === Tab: vert.glsl ===
#version 300 es 
in vec3 aPosition; void main() { gl_Position=vec4(aPosition*2.-1., 1.0); }

// === Tab: frag.glsl ===
#version 300 es
/*********
* made by Matthias Hurrle (@atzedent)
*/
precision highp float;
out vec4 O;
uniform float time;
uniform vec2 resolution;
uniform vec2 wheel;
#define FC gl_FragCoord.xy
#define R resolution
#define T (time+wheel.y/1e3)
#define S smoothstep
#define SE(v,s) S(s+1./MN,s-1./MN,v)
#define MN min(R.x,R.y)
#define hue(a) (.25+.6*cos(6.3*(a)+vec3(0,85,21)))
#define lum(a) dot(a,vec3(.21,.71,.07))
vec3 render(vec2 uv) {
	vec2 p=uv;
	vec3 col=vec3(0);
	uv*=1.2;
	float t=T;
	if (mod(T,20.)>10.) t=.0;
	for (float i=.0; i<2.; i++) {
		float
		a=atan(uv.x,uv.y)/6.28318,
		b=length(.1+round(uv*3.));
		uv=vec2(a*9.-b,a+log(b)-t);
		uv=fract(uv);
		uv=abs(uv)/dot(uv,uv)*1.5-1.-S(.2,-.2,sin(t/3.1415));
		uv*=mat2(cos(T-vec4(0,11,33,0)));
		col+=SE(length(uv),.25)*hue(t*.2+i*.25+T);
		uv*=i+1.;
	}
	if (t==.0) col=vec3(lum(col)); // the burnout
	return col;
}
#define AA
void main() {
	vec2 uv=(FC-.5*R)/MN;
	vec3 col=render(uv);
	#ifdef AA
	for (float x=.0; x<=1.; x++) {
		for (float y=.0; y<=1.; y++)
			col+=render(uv+(vec2(x,y)-.5)/R);
	}
	col/=5.;
	#endif
	// vignette
	vec2 c=FC/R;
	c*=1.-c.yx;
	float vig=c.x*c.y*25.;
	vig=pow(vig,.125);
	col*=vig;
	col=max(col,.08);
	O=vec4(col,1);
}

